import clsx from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: Parameters<typeof clsx>[0][]) {
  return twMerge(clsx(inputs));
}

// ============================================
// STANDARDIZED MUNYAKA INSTITUTIONAL HEADERS
// ============================================
// These three lines MUST appear at the very top of every CSV export
// and at the top of every PDF report generated by the system.

export const MUNYAKA_HEADERS = {
  schoolLine1: "MUNYAKA PRIMARY AND JUNIOR",
  schoolLine2: "P.O. BOX 5239, ELDORET",
  schoolLine3: "MOTTO: Knowledge Is Power",
} as const;

/**
 * Returns the three standard institutional header rows joined with newlines.
 * Callers that need an array (for spreadsheet-style exports) can use
 * `getMunyakaHeaderRows()` instead.
 */
export function getMunyakaHeaderText(): string {
  return [
    MUNYAKA_HEADERS.schoolLine1,
    MUNYAKA_HEADERS.schoolLine2,
    MUNYAKA_HEADERS.schoolLine3,
  ].join("\n");
}

/**
 * Returns the three standard institutional header rows as an array.
 * Use this when you need to prepend them as discrete CSV rows.
 */
export function getMunyakaHeaderRows(): string[] {
  return [
    MUNYAKA_HEADERS.schoolLine1,
    MUNYAKA_HEADERS.schoolLine2,
    MUNYAKA_HEADERS.schoolLine3,
  ];
}

// ============================================
// LEGACY SCHOOL CONTACT BLOCK (preserved)
// ============================================
// Kept for any callers that still need the full mailing block (postal
// address, phone, email). The new standard `MUNYAKA_HEADERS` above is
// the canonical institutional block going forward.

export const SCHOOL_HEADERS = {
  name: "MUNYAKA PRIMARY AND JUNIOR SCHOOL",
  motto: "MOTTO: KNOWLEDGE IS POWER",
  address: "P.O. BOX 5239-30100, ELDORET",
  phone: "+254 712 345 678",
  email: "info@munyaka.sc.ke"
};

/**
 * Returns the legacy school header block as a list of CSV lines. Use this
 * only when you need the full contact card in an export; most assessment
 * CSVs should use `getMunyakaHeaderRows()` instead.
 */
export const generateCSVHeader = (reportTitle: string, extraInfo?: string[]) => {
  const lines = [
    SCHOOL_HEADERS.name,
    SCHOOL_HEADERS.motto,
    SCHOOL_HEADERS.address,
    SCHOOL_HEADERS.phone,
    SCHOOL_HEADERS.email,
    "",
    reportTitle,
    ...(extraInfo || []),
    ""
  ];
  return lines;
};

// ============================================
// UNIFIED INJECTOR: prepend Munyaka institutional
// block to any CSV payload
// ============================================

/**
 * Prepends the standard Munyaka institutional header rows to a CSV payload.
 *
 * The result always begins with the three canonical lines:
 *   1. MUNYAKA PRIMARY AND JUNIOR
 *   2. P.O. BOX 5239, ELDORET
 *   3. MOTTO: Knowledge Is Power
 *
 * followed by an empty separator row, then whatever CSV content was passed in.
 * The function guarantees the BOM and Munyaka header are NOT duplicated if
 * the caller invokes it more than once.
 */
export function withMunyakaHeader(csvBody: string, options?: { includeReportTitle?: string; extraLines?: string[]; }): string {
  if (typeof csvBody !== 'string') {
    throw new TypeError('withMunyakaHeader: csvBody must be a string');
  }

  // BOM for Excel encoding detection
  const bom = '\uFEFF';

  // If the payload already starts with the standard header, return as-is.
  if (
    csvBody.includes(MUNYAKA_HEADERS.schoolLine1) &&
    csvBody.includes(MUNYAKA_HEADERS.schoolLine2) &&
    csvBody.includes(MUNYAKA_HEADERS.schoolLine3)
  ) {
    return csvBody.startsWith(bom) ? csvBody : bom + csvBody;
  }

  const headerLines = [
    MUNYAKA_HEADERS.schoolLine1,
    MUNYAKA_HEADERS.schoolLine2,
    MUNYAKA_HEADERS.schoolLine3,
  ];

  const additionalLines: string[] = [];
  if (options?.includeReportTitle) {
    additionalLines.push(`Report: ${options.includeReportTitle}`);
  }
  if (options?.extraLines && options.extraLines.length > 0) {
    additionalLines.push(...options.extraLines);
  }

  const allHeaderLines = [...headerLines, ...additionalLines, ''];

  return bom + allHeaderLines.join('\n') + '\n' + csvBody;
}

// ============================================
// CSV-EXPORT PIPELINE (existing behavior preserved)
// ============================================

/**
 * Backward-compatible wrapper that builds a CSV string and routes it through
 * the unified file download pipeline. Prepends a UTF-8 BOM for Excel
 * compatibility, and resolves with a `FileDownloadResult` so callers can
 * update their UI state in response to success/failure.
 */
export async function downloadCSV(csvContent: string, fileName: string) {
  // Auto-prepend the standard Munyaka institutional header unless the caller
  // already provided it themselves.
  const withHeader = withMunyakaHeader(csvContent);

  const { downloadFile } = await import('./fileDownloader');
  return downloadFile({
    filename: fileName,
    data: withHeader,
    mimeType: 'text/csv;charset=utf-8;',
    fileType: 'csv',
  });
}

/**
 * Backward-compatible wrapper for downloading text/JSON content via the
 * unified file downloader. CSV exports go through `downloadCSV` instead so
 * the institutional header is always applied.
 */
export async function downloadText(textContent: string, fileName: string) {
  const { downloadFile } = await import('./fileDownloader');
  return downloadFile({
    filename: fileName,
    data: textContent,
    mimeType: 'text/plain;charset=utf-8',
    fileType: 'txt',
  });
}

/**
 * Backward-compatible wrapper for downloading from a URL by triggering
 * a standard anchor element. (Used for blob: or http(s) URLs that have
 * already been produced elsewhere.)
 */
export async function downloadFromUrl(url: string, fileName: string, _mimeType: string = 'application/octet-stream') {
  const { downloadFile } = await import('./fileDownloader');
  // We don't have raw data for arbitrary URLs, so we fetch and re-route
  // through the unified pipeline so the user gets a consistent toast.
  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`Failed to fetch file: ${response.statusText}`);
    const blob = await response.blob();
    const mimeType = blob.type || 'application/octet-stream';
    const reader = new FileReader();
    const data: string = await new Promise((resolve, reject) => {
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = () => reject(reader.error);
      reader.readAsDataURL(blob);
    });
    const base64 = data.split(',')[1] || data;
    return downloadFile({
      filename: fileName,
      data: base64,
      mimeType,
      isBase64: true,
    });
  } catch (err) {
    const { downloadFile: df } = await import('./fileDownloader');
    return df({
      filename: fileName,
      data: '',
      mimeType: 'text/plain',
      errorMessage: 'Download failed. Please check app permissions.',
    });
  }
}

/**
 * Backward-compatible wrapper for downloading JSON content via the
 * unified file downloader.
 */
export async function downloadFile(content: string, fileName: string, mimeType: string = 'application/json') {
  const { downloadFile: df } = await import('./fileDownloader');
  return df({
    filename: fileName,
    data: content,
    mimeType,
    isBase64: false,
  });
}